    "js": "// 7. Current Date & Time\nfunction updateDateTime() {\n  const now = new Date();\n  const options = {\n    weekday: 'long',\n    year: 'numeric',\n    month: 'long',\n    day: 'numeric',\n    hour: '2-digit',\n    minute: '2-digit'\n  };\n  document.getElementById('currentDateTime').textContent = now.toLocaleDateString('en-US', options);\n}\nsetInterval(updateDateTime, 1000);\nupdateDateTime();\n\nconst startCounters = () => {\n  counters.forEach(counter => {\n    const updateCount = () => {\n      const target = +counter.getAttribute('data-target');\n      const count = +counter.innerText;\n      const inc = target / speed;\n\n      if (count < target) {\n        counter.innerText = Math.ceil(count + inc);\n        setTimeout(updateCount, 10);\n      } else {\n        counter.innerText = target;\n      }\n    };\n    updateCount();\n  });\n};\n\n// Toggle collapse / mobile menu / accordion\ndocument.querySelectorAll('[data-bs-toggle=\"collapse\"]').forEach((trigger) => {\n  trigger.addEventListener('click', (e) => {\n    e.preventDefault();\n    const targetSel = trigger.getAttribute('data-bs-target') || trigger.getAttribute('href');\n    const target = targetSel ? document.querySelector(targetSel) : null;\n    if (!target) return;\n    const parentSel = target.getAttribute('data-bs-parent');\n    if (parentSel) {\n      const parent = document.querySelector(parentSel);\n      if (parent) {\n        parent.querySelectorAll('.collapse.show').forEach((sib) => {\n          if (sib !== target) {\n            sib.classList.remove('show');\n            const btn = parent.querySelector('[data-bs-target=\"#' + sib.id + '\"]');\n            if (btn) {\n              btn.classList.add('collapsed');\n              btn.setAttribute('aria-expanded', 'false');\n            }\n          }\n        });\n      }\n    }\n    const isOpen = target.classList.toggle('show');\n    trigger.classList.toggle('collapsed', !isOpen);\n    trigger.setAttribute('aria-expanded', String(isOpen));\n  });\n});",
