    "js": "// Carousel slider controls\ndocument.querySelectorAll('.carousel').forEach((carousel) => {\n  const items = Array.from(carousel.querySelectorAll('.carousel-item'));\n  if (!items.length) return;\n  const showSlide = (idx) => {\n    const next = ((idx % items.length) + items.length) % items.length;\n    items.forEach((el, i) => el.classList.toggle('active', i === next));\n    carousel.querySelectorAll('[data-bs-slide-to]').forEach((dot, i) => {\n      dot.classList.toggle('active', i === next);\n      if (i === next) dot.setAttribute('aria-current', 'true');\n      else dot.removeAttribute('aria-current');\n    });\n  };\n  carousel.querySelectorAll('[data-bs-slide]').forEach((btn) => {\n    btn.addEventListener('click', (e) => {\n      e.preventDefault();\n      const cur = items.findIndex((el) => el.classList.contains('active'));\n      showSlide(btn.getAttribute('data-bs-slide') === 'prev' ? cur - 1 : cur + 1);\n    });\n  });\n  carousel.querySelectorAll('[data-bs-slide-to]').forEach((dot) => {\n    dot.addEventListener('click', (e) => {\n      e.preventDefault();\n      showSlide(parseInt(dot.getAttribute('data-bs-slide-to'), 10) || 0);\n    });\n  });\n  if (carousel.getAttribute('data-bs-ride') === 'carousel') {\n    const interval = parseInt(carousel.getAttribute('data-bs-interval'), 10) || 5000;\n    setInterval(() => {\n      const cur = items.findIndex((el) => el.classList.contains('active'));\n      showSlide(cur + 1);\n    }, interval);\n  }\n});",
